// Detects generated or minified files so the parser can keep their chunking cheap and bounded.

export interface GeneratedVerdict {
  generated: boolean;
  /** `path`, `marker`, `sourcemap`, `minified` or `long-lines` when generated. */
  reason?: string;
}

const NOT_GENERATED: GeneratedVerdict = { generated: false };

// File names that are produced by tools. Matched against the lower-cased path.
const GENERATED_PATH = new RegExp([
  String.raw`\.min\.(?:js|mjs|cjs|css)$`,
  String.raw`\.bundle\.(?:js|mjs|cjs|css)$`,
  String.raw`\.pb\.(?:go|cc|h|swift)$`,
  String.raw`\.pb\.gw\.go$`,
  String.raw`_pb2(?:_grpc)?\.pyi?$`,
  String.raw`_pb\.(?:js|d\.ts)$`,
  String.raw`\.(?:g|freezed|gr|mocks)\.dart$`,
  String.raw`\.(?:designer|g|g\.i|generated)\.cs$`,
  String.raw`\.generated\.(?:ts|tsx|js|go|java|kt|rs|py|php)$`,
  String.raw`(?:^|/)zz_generated[^/]*$`,
  String.raw`_generated\.(?:go|rs|ts|py)$`,
  String.raw`\.gen\.(?:go|ts|rs)$`,
  String.raw`(?:^|/)(?:package-lock\.json|npm-shrinkwrap\.json|yarn\.lock|pnpm-lock\.yaml|cargo\.lock|poetry\.lock|pipfile\.lock|composer\.lock|gemfile\.lock|go\.sum)$`,
].join('|'));

// The marker must open the comment ("Code generated by ...", "This file was automatically generated"), so a doc
// comment that merely mentions generated output ("... the ones that are auto-generated") does not count.
const MARKER_OPENING = /^[\W_]*(?:(?:note|warning|caution|attention|important)\W+)?(?:code |this (?:file|code|class|module|document|source) (?:was |is |has been )?)?(?:automatically |auto[- ]?|machine[- ])?generated\b/i;
// Tags and tool names that identify generated files wherever they appear in the header comments.
const MARKER_ANYWHERE = new RegExp([
  String.raw`(?:^|\s)@generated\b`,
  String.raw`<auto-generated`,
  String.raw`\bdo not (?:edit|modify)\b.*\b(?:generated|manually|by hand)\b`,
  String.raw`\bprotoc-gen-`,
  String.raw`\b(?:graphql[- ]code[- ]?generator|graphql-codegen|openapi[- ]generator|swagger[- ]codegen|sqlc generate|thrift compiler)\b`,
].join('|'), 'i');

const COMMENT_PREFIX = /^\s*(?:\/\/+|\/\*+|\*+|#+|--+|;+|%+|<!--|\(\*+|"""|''')\s*/;
const BLOCK_OPEN = /\/\*(?!.*\*\/)|"""(?!.*""")|'''(?!.*''')|\(\*(?!.*\*\))|<!--(?!.*-->)/;
const BLOCK_CLOSE = /\*\/|"""|'''|\*\)|-->/;
// Lines that may precede the header comment without ending it.
const PROLOGUE = /^\s*(?:<\?php|<\?xml\b|<!doctype\b|#!|['"]use strict['"]|@file:)/i;
const SOURCE_MAP = /(?:\/\/|\/\*)[#@]\s*sourceMappingURL=/;

const HEAD_CHARS = 4096;
const HEAD_LINES = 40;
const TAIL_CHARS = 600;
const LONG_LINE = 2000;
const MIN_CHARS_FOR_AVERAGE = 4096;
const AVERAGE_LINE_LIMIT = 300;
const PROSE = /\.(?:md|markdown|mdx|txt|rst|adoc|org|tex)$/i;

/** Scans the leading comment block (everything before the first code line) for generator signatures. */
function headHasMarker(text: string): boolean {
  let inBlock = false;
  for (const line of text.slice(0, HEAD_CHARS).split('\n', HEAD_LINES)) {
    if (!line.trim() || PROLOGUE.test(line)) continue;
    const commentLike = inBlock || COMMENT_PREFIX.test(line);
    if (!commentLike) return false;
    const content = line.replace(COMMENT_PREFIX, '');
    if (MARKER_OPENING.test(content) || MARKER_ANYWHERE.test(content)) return true;
    if (!inBlock) inBlock = BLOCK_OPEN.test(line);
    else if (BLOCK_CLOSE.test(line)) inBlock = false;
  }
  return false;
}

/**
 * Decides whether a file is generated or minified. Only the head and tail are inspected for
 * markers, and marker words must sit on comment lines, so prose that merely mentions
 * "generated" does not trigger it.
 */
export function detectGenerated(path: string, text: string, lines?: readonly string[]): GeneratedVerdict {
  const lower = path.toLowerCase();
  if (GENERATED_PATH.test(lower)) return { generated: true, reason: 'path' };
  if (headHasMarker(text)) return { generated: true, reason: 'marker' };
  if (SOURCE_MAP.test(text.slice(-TAIL_CHARS))) return { generated: true, reason: 'sourcemap' };
  if (PROSE.test(lower)) return NOT_GENERATED;
  const all = lines ?? text.split('\n');
  let longChars = 0;
  for (const line of all) if (line.length > LONG_LINE) longChars += line.length;
  if (longChars > 0 && longChars * 2 > text.length) return { generated: true, reason: 'long-lines' };
  if (text.length >= MIN_CHARS_FOR_AVERAGE && text.length / all.length > AVERAGE_LINE_LIMIT) return { generated: true, reason: 'minified' };
  return NOT_GENERATED;
}
